rng=np.random.default_rng(62819)
def sample(n):
 X=np.empty((n,20));X[:,0]=rng.uniform(-4.2,4,n);X[:,1:10]=rng.integers(0,2,(n,9));X[:,10:]=rng.uniform(0,10,(n,10));return X

X=sample(60000);y=predict(X).reshape(-1)
V=sample(15000);v=predict(V).reshape(-1)
knots={0:[-2,0,2]}
for i in range(10,20):knots[i]=[2.5,5,7.5]
knots[12]=[1,2.5,4,5.5,7,8.5]
features=[(i,None) for i in range(20)]+[(i,k) for i in knots for k in knots[i]]
def basis(Z):
 return np.column_stack([Z[:,i] if k is None else np.maximum(Z[:,i]-k,0) for i,k in features])
B=basis(X);C=basis(V)
m=B.mean(0);s=B.std(0);B=(B-m)/s;C=(C-m)/s
ff=[(a,-1) for a in range(B.shape[1])]+[(a,b) for a in range(B.shape[1]) for b in range(a+1,B.shape[1]) if features[a][0]!=features[b][0]]
T=np.column_stack([np.ones(len(B))]+[B[:,a] if b==-1 else B[:,a]*B[:,b] for a,b in ff])
U=np.column_stack([np.ones(len(C))]+[C[:,a] if b==-1 else C[:,a]*C[:,b] for a,b in ff])
G=T.T@T/len(T);z=T.T@y/len(T)
nb=1+B.shape[1];G0=G[:nb,:nb];cross=G[:nb,nb:];A=np.linalg.solve(G0,cross)
H=G[nb:,nb:]-cross.T@A;r=z[nb:]-cross.T@np.linalg.solve(G0,z[:nb])
H=H.copy();r=r.copy();selected=list(range(nb));active=np.ones(len(r),dtype=bool)

for it in range(120):
 diag=np.maximum(np.diag(H),1e-10);score=r*r/diag;score[~active]=-1
 j=int(np.argmax(score));col=H[:,j].copy();dj=diag[j]
 H-=np.outer(col,col)/dj;r-=col*(r[j]/dj);selected.append(j+nb);active[j]=False
selectedff=[ff[i-1] for i in selected[1:]]
def design(Z):
 F=(basis(Z)-m)/s
 return np.column_stack([np.ones(len(Z))]+[F[:,a] if b==-1 else F[:,a]*F[:,b] for a,b in selectedff])
Gf=np.zeros((len(selected),len(selected)));zf=np.zeros(len(selected))
for n in range(12):
 Z=sample(20000);D=design(Z);yy=predict(Z).reshape(-1)
 Gf+=D.T@D;zf+=D.T@yy
coef=np.linalg.solve(Gf+np.eye(len(selected))*.001,zf)
Z=sample(40000);yy=predict(Z).reshape(-1);yp=design(Z)@coef;err=yp-yy
p=1/(1+np.exp(-yp));q=1/(1+np.exp(-yy))
print('FINAL',len(coef),'RMSE',np.sqrt(np.mean(err*err)),'R2',1-np.mean(err*err)/np.var(yy),'pMAE',np.mean(np.abs(p-q)),'pRMSE',np.sqrt(np.mean((p-q)**2)),'abslogit_quantiles',np.quantile(np.abs(err),[.5,.9,.95,.99,1]))
print('FINAL features',selectedff)
intercept=float(coef[0]);main=np.zeros(len(features));products=[]
for cc,(a,b) in zip(coef[1:],selectedff):
 if b==-1:
  c=cc/s[a];main[a]+=c;intercept-=c*m[a]
 else:
  c=cc/(s[a]*s[b]);main[a]-=c*m[b];main[b]-=c*m[a];intercept+=c*m[a]*m[b]
  i,ka=features[a];j,kb=features[b]
  if ka is None and kb is None:
   products.append({'inputs':[INPUTS[i],INPUTS[j]],'coef':round(float(c),7)})
  else:
   if ka is None:
    if i==0:
     ka=-4.2;main[b]-=4.2*c
    else:ka=0
   if kb is None:
    if j==0:
     kb=-4.2;main[a]-=4.2*c
    else:kb=0
   products.append({'inputs':[INPUTS[i],INPUTS[j]],'knots':[ka,kb],'coef':round(float(c),7)})
terms=[]
for (i,k),c in zip(features,main):
 if k is None:terms.append({'input':INPUTS[i],'type':'linear','coef':round(float(c),7)})
 else:terms.append({'input':INPUTS[i],'type':'hinge','knot':k,'coef':round(float(c),7)})
surrogate={'intercept':round(intercept,7),'terms':terms,'interactions':products}
print('SURROGATE',str(surrogate).replace("'",'"'))
def surpredict(Z):
 out=np.zeros(len(Z))+surrogate['intercept']
 for t in surrogate['terms']:
  x=Z[:,INPUTS.index(t['input'])]
  if t['type']=='hinge':x=np.maximum(x-t['knot'],0)
  out+=t['coef']*x
 for t in surrogate['interactions']:
  i,j=[INPUTS.index(i) for i in t['inputs']];a=Z[:,i];b=Z[:,j]
  if 'knots' in t:
   a=np.maximum(a-t['knots'][0],0);b=np.maximum(b-t['knots'][1],0)
  out+=t['coef']*a*b
 return out
print('conversion check',np.max(np.abs(surpredict(Z)-yp)))
A=np.zeros((1,20));A[:,10:]=5
print('reference',predict(A),surpredict(A))
for i in [0,2,7,12,15,19]:
 vals=np.linspace(-4.2,4,9) if i==0 else (np.array([0,1]) if i<10 else np.linspace(0,10,11))
 AA=np.repeat(A,len(vals),axis=0);AA[:,i]=vals
 print('slice',INPUTS[i],'network',np.round(predict(AA),4),'surrogate',np.round(surpredict(AA),4))

